excels.excel:

EXPORT WITH SHEET="部门费用对比", HEADER=true,
    MAPPING={"a":"部门","b":"预算","c":"实际","d":"差异"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00"},
    FORMULAS={
        D2:'C2-B2',D3:'C3-B3',D4:'C4-B4',D5:'C5-B5',
        B6:'SUM(B2:B5)',C6:'SUM(C2:C5)',D6:'C6-B6'
    },
    STYLE={ROW 6:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}},
    GRAPH={TYPE=BAR3D, TITLE="部门费用对比图", CATEGORY_AXIS=部门, VALUE_AXIS=金额,
           CATEGORIES=["销售部","研发部","客服部","运营部"],
           SERIES=[
               {NAME=预算, DATA=[120000,180000,90000,150000]},
               {NAME=实际, DATA=[135000,165000,105000,142000]}
           ]}
